import { ChangeEvent, FormEvent, useEffect, useMemo, useRef, useState } from 'react'
import {
  AlertTriangle, ArrowLeft, ArrowRight, Bot, Building2, CalendarRange, Camera, Check, CheckCircle2,
  ChevronDown, ChevronRight, CircleDollarSign, ClipboardCheck, Construction, Copy,
  Download, FileSearch, FileText, Fingerprint, GalleryHorizontalEnd, HardHat, Home,
  ImagePlus, Landmark, Layers3, ListChecks, LoaderCircle, LogOut, Menu, Mic, MicOff,
  Plus, RefreshCw, Ruler, Search, Send, Settings2, ShieldCheck, Sparkles, UploadCloud,
  Users, WalletCards, WandSparkles, X
} from 'lucide-react'
import StageGuide from './StageGuide'
