type User = { id:number; name:string; email:string; role:'admin'|'team'|'client' }
type Project = { id:number; name:string; city?:string; address?:string; client_name?:string; status:string; budget:number|string; spent:number|string; committed?:number|string; updated_at?:string }
type Task = { id:number; code:string; stage_key:string; discipline:string; title:string; detail?:string; role?:string; required:boolean; priority:string; status:'pending'|'done'|'na'; client_action:boolean; is_custom:boolean; completed_by_name?:string }
type Stage = { num:string; key:string; title:string; summary:string; total:number; applicable:number; done:number; progress:number; order:number }
type Photo = { id:number; data_url:string; caption?:string; stage_key?:string; task_id?:number; task_title?:string; ai_summary?:string; ai_confidence?:number|string; ai_tags?:string[]; ai_safety?:string[]; uploaded_by_name?:string; created_at:string }
type Passport = { id:number; system_type:string; zone?:string; title:string; description?:string; photo_url?:string; warranty_until?:string; supplier?:string }
type Bundle = { project:Project; profile:any; workflowVersion?:string; tasks:Task[]; events:any[]; passport:Passport[]; photos:Photo[]; stages:Stage[]; disciplines:Record<string,{total:number;done:number}>; summary:{ total:number; done:number; na:number; applicable:number; progress:number; nextTask?:Task|null } }
type View = 'dashboard'|'planning'|'field'|'workforce'|'roadmap'|'photos'|'architecture'|'engineering'|'city'|'safety'|'documents'|'finance'|'memory'|'copilot'|'settings'
type AgentTab = 'voice'|'vision'|'report'
type VoiceAnalysis = { summary:string; action:'done'|'reopen'|'na'|'create_task'|'create_stage'|'query'|'log'|'attention'; suggestions:{id:number;title:string;stageKey?:string;discipline?:string;confidence?:number}[]; safety:string[]; nextStep?:string; answer?:string; createLabel?:string; confidence?:number; mode?:string }
type VisionAnalysis = { title:string; category:string; summary:string; stageKey?:string|null; discipline:string; taskIds:number[]; checklistSuggestions:string[]; observations:string[]; safety:string[]; architecture:string[]; municipality:string[]; extracted:Record<string,any>; confidence:number; mode?:string }
type ReportResult = { id:number; title:string; content:string; periodLabel:string; mode?:string; created_at?:string }

const META:Record<string,{label:string;color:string}> = {
  arquitetura:{label:'Arquitetura',color:'#B9633E'}, engenharia:{label:'Engenharia Civil',color:'#365E76'},
  prefeitura:{label:'Prefeitura',color:'#7D633B'}, federal:{label:'Federal',color:'#5C6870'},
  sst:{label:'Segurança',color:'#B34C45'}, financeiro:{label:'Financeiro',color:'#5B755E'},
  suprimentos:{label:'Suprimentos',color:'#87723E'}, gestao:{label:'Gestão',color:'#536A60'},
  qualidade:{label:'Controle técnico',color:'#47717B'}, cliente:{label:'Cliente',color:'#795D82'},
  passaporte:{label:'Memória',color:'#376252'}
}
const STAGE_ICONS = [Landmark,Ruler,FileText,Layers3,WalletCards,HardHat,Construction,Building2,Building2,Construction,ShieldCheck,ClipboardCheck,Home,CheckCircle2,Fingerprint]
const money=(v:any)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(Number(v)||0)
const date=(v?:string)=>v?new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(v)):'—'
const human=(v='')=>String(v).replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())
const role=(v?:string)=>({cliente:'Proprietário',arquiteto:'Arquiteto(a)',engenheiro_civil:'Eng. Civil',engenheiro_producao:'Gestão / Produção',engenheiro_seguranca:'Eng. Segurança',engenheiro_eletricista:'Eng. Eletricista',profissional_habilitado:'Profissional habilitado',equipe:'Equipe'} as any)[v||'']||human(v||'Equipe')
async function api<T=any>(url:string,options:RequestInit={}):Promise<T>{const r=await fetch(url,{...options,credentials:'include',headers:{'Content-Type':'application/json',...(options.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Erro na operação');return d}
async function imageToDataUrl(file:File){return await new Promise<string>((resolve,reject)=>{const img=new Image(),reader=new FileReader();reader.onload=()=>{img.onload=()=>{const max=1440,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.round(img.width*scale),h=Math.round(img.height*scale),c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');if(!ctx)return reject(new Error('Falha ao processar imagem'));ctx.drawImage(img,0,0,w,h);resolve(c.toDataURL('image/jpeg',.76))};img.onerror=()=>reject(new Error('Imagem inválida'));img.src=String(reader.result)};reader.onerror=()=>reject(new Error('Falha ao ler imagem'));reader.readAsDataURL(file)})}
async function fileToDataUrl(file:File){if(file.type.startsWith('image/'))return imageToDataUrl(file);return await new Promise<string>((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=()=>reject(new Error('Falha ao ler arquivo'));r.readAsDataURL(file)})}

export default function AppOSV5(){
  const[user,setUser]=useState<User|null>(null),[loading,setLoading]=useState(true)
  useEffect(()=>{api('/api/me').then(r=>setUser(r.user)).catch(()=>setUser(null)).finally(()=>setLoading(false))},[])
  if(loading)return <Splash/>
  if(!user)return <Login onLogin={setUser}/>
  return <Portal user={user} onLogout={()=>setUser(null)}/>
}

function Brand(){return <div className="v4-brand"><span aria-hidden="true">V</span><div><b>VIÇO</b><small>ENGENHARIA + INTELIGÊNCIA</small></div></div>}
function Splash(){return <div className="v4-splash"><Brand/><div className="v4-loader"><i/></div></div>}

function Login({onLogin}:{onLogin:(u:User)=>void}){
  const[email,setEmail]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('')
  async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email,password})});onLogin(r.user)}catch(e:any){setError(e.message)}finally{setBusy(false)}}
  return <div className="v4-login"><section className="v4-login-visual"><div className="v4-grid-bg"/><Brand/><div className="v4-login-copy"><span>ENGENHARIA, DADOS E INTELIGÊNCIA PARA O CANTEIRO.</span><h1>Sua obra.<br/>Mais clareza.<br/>Melhores decisões.</h1><p>Conecte a equipe, acompanhe as pendências e mantenha os registros da obra em um só lugar. Do canteiro à próxima decisão.</p><div className="v4-login-pills"><em><Mic size={16}/> voz</em><em><Camera size={16}/> fotos</em><em><FileSearch size={16}/> PDF</em><em><ClipboardCheck size={16}/> relatórios</em></div></div><footer>PLANEJAR <i/> APROVAR <i/> EXECUTAR <i/> COMPROVAR <i/> ENTREGAR</footer></section><section className="v4-login-form"><form onSubmit={submit}><span>PORTAL DA OBRA</span><h2>Bem-vindo à VIÇO</h2><p>Cliente e equipe enxergam a mesma obra, com níveis de acesso diferentes.</p><label>E-mail<input type="email" autoComplete="username" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Senha<input type="password" autoComplete="current-password" value={password} onChange={e=>setPassword(e.target.value)} required/></label>{error&&<div className="v4-form-error">{error}</div>}<button disabled={busy}>{busy?'Entrando…':'Entrar'} <ArrowRight size={17}/></button></form></section></div>
}

function Portal({user,onLogout}:{user:User;onLogout:()=>void}){
  const staff=['admin','team'].includes(user.role)
  const [detailed,setDetailed]=useState(false),[createOpen,setCreateOpen]=useState(false),[loadError,setLoadError]=useState('')
  const loadGeneration=useRef(0)
  const[projects,setProjects]=useState<Project[]>([]),[projectId,setProjectId]=useState<number|null>(null),[b,setB]=useState<Bundle|null>(null)
  const[view,setView]=useState<View>('dashboard'),[menu,setMenu]=useState(false),[loading,setLoading]=useState(true),[toast,setToast]=useState(''),[selectedStage,setSelectedStage]=useState<string|null>(null),[copilotTab,setCopilotTab]=useState<AgentTab>('voice')
  async function loadProjects(){const r=await api('/api/projects');setProjects(r.projects);if(!projectId&&r.projects[0])setProjectId(r.projects[0].id);setLoading(false)}
  async function load(id=projectId){if(!id)return;const generation=++loadGeneration.current;setLoadError('');try{const data=await api(`/api/os/projects/${id}`);if(generation===loadGeneration.current)setB(data)}catch(e:any){if(generation===loadGeneration.current)setLoadError(e.message);throw e}}
  useEffect(()=>{loadProjects().catch(()=>setLoading(false))},[])
  useEffect(()=>{if(projectId){setB(null);load(projectId).catch(e=>notify(e.message))}},[projectId])
  useEffect(()=>{const refresh=()=>load().catch(()=>{});window.addEventListener('obra360:refresh',refresh);return()=>window.removeEventListener('obra360:refresh',refresh)},[projectId])
  async function logout(){await api('/api/auth/logout',{method:'POST'}).catch(()=>{});onLogout()}
  function notify(m:string){setToast(m);setTimeout(()=>setToast(''),3600)}
  function openStage(key:string){setSelectedStage(key);setView('roadmap');setMenu(false)}
  function openCopilot(tab:AgentTab='voice'){setCopilotTab(tab);setView('copilot')}
  if(loading)return <Splash/>
  if(!projects.length)return <EmptyProjects staff={staff} reload={loadProjects} logout={logout}/>
  const nav:[View,string,any][]=[
    ['dashboard',staff?'Central da obra':'Minha obra',Home],...(staff?[['planning','Planejamento',CalendarRange] as [View,string,any],['field','Campo & RDO',ClipboardCheck] as [View,string,any],['workforce','Equipes & capacidade',Users] as [View,string,any]]:[]),['roadmap','Etapas e checklist',ListChecks],['photos','Fotos & evidências',GalleryHorizontalEnd],
    ['architecture','Arquitetura',Ruler],['engineering','Engenharia Civil',Construction],['city','Prefeitura & licenças',Landmark],['safety','Segurança do trabalho',HardHat],['documents','Documentos',FileText],
    ['finance','Custos',WalletCards],['memory','Memória do imóvel',Fingerprint],['copilot','Assistente da obra',Sparkles],
    ...(staff?[['settings','Dados da obra',Settings2] as [View,string,any]]:[])
  ]
  return <div className="v4-shell"><aside className={`v4-side ${menu?'open':''}`}><div className="v4-side-head"><Brand/><button aria-label="Fechar menu" onClick={()=>setMenu(false)}><X size={18}/></button></div><div className="v4-active-work"><small>OBRA ATIVA</small><b>{b?.project.name||'Carregando…'}</b><span>{b?.project.city||'Município não informado'}</span></div><nav>{nav.filter(([k])=>staff||detailed||['dashboard','roadmap','photos','finance','memory','copilot'].includes(k)).map(([k,l,I])=><button key={k} className={`${view===k?'active':''} ${k==='copilot'?'copilot-nav':''}`} onClick={()=>{setView(k);setMenu(false);if(k!=='roadmap')setSelectedStage(null)}}><I size={18}/><span>{l}</span>{k==='roadmap'&&b?<em>{b.summary.progress}%</em>:null}{k==='copilot'?<strong>IA</strong>:null}</button>)}</nav>{!staff&&<button className="vico-details-toggle" onClick={()=>setDetailed(!detailed)}>{detailed?'Recolher áreas técnicas':'Ver áreas técnicas'}</button>}<div className="v4-side-user"><span>{user.name[0]?.toUpperCase()}</span><div><b>{user.name}</b><small>{user.role==='client'?'Proprietário':'Equipe técnica'}</small></div><button aria-label="Sair da conta" onClick={logout}><LogOut size={16}/></button></div></aside>{menu&&<button className="vico-menu-backdrop" aria-label="Fechar menu" onClick={()=>setMenu(false)}/>}<main className="v4-main"><header className="v4-top"><button className="v4-menu-button" aria-label="Abrir menu" onClick={()=>setMenu(true)}><Menu size={20}/></button><div className="v4-project-select"><Building2 size={16}/><select aria-label="Selecionar obra" value={projectId||''} onChange={e=>setProjectId(Number(e.target.value))}>{projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><ChevronDown size={14}/></div><div className="v4-top-actions">{staff&&<button onClick={()=>setCreateOpen(!createOpen)}><Plus size={15}/><span>Nova obra</span></button>}<button className="v4-agent-shortcut" onClick={()=>openCopilot('voice')}><Mic size={15}/><span>Falar com a obra</span></button><button onClick={()=>load().catch(e=>notify(e.message))}><RefreshCw size={15}/><span>Atualizar</span></button></div></header>{toast&&<div role="status" className="v4-toast">{toast}</div>}{createOpen&&staff&&<section className="v4-page"><CreateProject reload={async()=>{await loadProjects();setCreateOpen(false)}}/></section>}{loadError?<section className="v4-page"><div role="alert" className="v4-form-error">{loadError}</div><button className="v4-primary" onClick={()=>load().catch(()=>{})}>Tentar novamente</button></section>:!b?<div className="v4-loading">Carregando dados da obra…</div>:!b.profile?<Onboarding project={b.project} staff={staff} reload={load}/>:<Router key={b.project.id} view={view} setView={setView} b={b} user={user} staff={staff} reload={load} notify={notify} selectedStage={selectedStage} setSelectedStage={setSelectedStage} openStage={openStage} openCopilot={openCopilot} copilotTab={copilotTab} setCopilotTab={setCopilotTab}/>}</main></div>
}

function EmptyProjects({staff,reload,logout}:{staff:boolean;reload:()=>void;logout:()=>void}){return <div className="v4-empty-projects"><header><Brand/><button onClick={logout}><LogOut size={16}/> Sair</button></header><main><Building2 size={40}/><span>VIÇO · PORTAL DA OBRA</span><h1>{staff?'Crie a primeira obra':'Nenhuma obra vinculada'}</h1><p>{staff?'Você informa o básico e o sistema monta a jornada inicial automaticamente.':'Solicite à equipe o vínculo do seu acesso.'}</p>{staff&&<CreateProject reload={reload}/>}</main></div>}
function CreateProject({reload}:{reload:()=>void}){const[open,setOpen]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError('');try{await api('/api/projects',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget).entries()))});setOpen(false);reload()}catch(e:any){setError(e.message)}finally{setBusy(false)}}if(!open)return <button className="v4-primary" onClick={()=>setOpen(true)}><Plus size={17}/> Criar obra</button>;return <form className="v4-card-form" onSubmit={submit}><div className="v4-fields"><label>Nome<input name="name" required/></label><label>Município<input name="city" placeholder="Viçosa, MG"/></label><label>Cliente<input name="clientName"/></label><label>Orçamento inicial<input name="budget" type="number"/></label></div>{error&&<div className="v4-form-error">{error}</div>}<div className="v4-form-actions"><button type="button" onClick={()=>setOpen(false)}>Cancelar</button><button className="v4-primary" disabled={busy}>{busy?'Criando…':'Criar'}</button></div></form>}

function Onboarding({project,staff,reload}:{project:Project;staff:boolean;reload:()=>void}){
  const[step,setStep]=useState(0),[busy,setBusy]=useState(false),[error,setError]=useState('')
  const[p,setP]=useState<any>({city:project.city||'',state:'MG',kind:'casa_nova',area:'',floors:1,slope:'plano',earthwork:false,basement:false,pool:false,elevator:false,solar:false,gas:false,treeRemoval:false,demolition:false,hasEmployees:false,multipleContractors:true,workAtHeight:false})
  if(!staff)return <div className="v4-readonly-setup"><Sparkles size={30}/><h2>A equipe está preparando a jornada desta obra.</h2><p>Assim que o perfil for confirmado, o painel e as etapas serão liberados.</p></div>
  async function finish(){setBusy(true);setError('');try{await api(`/api/os/projects/${project.id}/profile`,{method:'PUT',body:JSON.stringify(p)});await reload()}catch(e:any){setError(e.message)}finally{setBusy(false)}}
  return <div className="v4-setup"><div className="v4-setup-meter">{[0,1,2,3].map(i=><i key={i} className={i<=step?'active':''}/>)}</div><section><span>{step+1} DE 4</span>{step===0&&<><h1>Que obra é essa?</h1><p>Com essas respostas a VIÇO monta o roteiro inicial.</p><div className="v4-choice-grid">{[['casa_nova','Casa nova'],['predio_residencial','Prédio residencial'],['comercial_novo','Comercial'],['reforma','Reforma'],['ampliacao','Ampliação']].map(([v,l])=><button type="button" key={v} className={p.kind===v?'selected':''} onClick={()=>setP({...p,kind:v})}><Building2 size={22}/><b>{l}</b></button>)}</div><div className="v4-fields"><label>Município<input value={p.city} onChange={e=>setP({...p,city:e.target.value})}/></label><label>Área aproximada (m²)<input type="number" value={p.area} onChange={e=>setP({...p,area:e.target.value})}/></label><label>Pavimentos<input type="number" min="1" value={p.floors} onChange={e=>setP({...p,floors:Number(e.target.value)})}/></label></div></>}{step===1&&<><h1>Como é o terreno?</h1><div className="v4-toggle-grid"><Toggle label="Movimentação relevante de terra" value={p.earthwork} set={v=>setP({...p,earthwork:v})}/><Toggle label="Inclinação acentuada" value={p.slope==='acentuado'} set={v=>setP({...p,slope:v?'acentuado':'plano'})}/><Toggle label="Subsolo" value={p.basement} set={v=>setP({...p,basement:v})}/><Toggle label="Demolição" value={p.demolition} set={v=>setP({...p,demolition:v})}/><Toggle label="Intervenção em árvore" value={p.treeRemoval} set={v=>setP({...p,treeRemoval:v})}/></div></>}{step===2&&<><h1>O que a obra terá?</h1><div className="v4-toggle-grid"><Toggle label="Piscina" value={p.pool} set={v=>setP({...p,pool:v})}/><Toggle label="Elevador" value={p.elevator} set={v=>setP({...p,elevator:v})}/><Toggle label="Energia solar" value={p.solar} set={v=>setP({...p,solar:v})}/><Toggle label="Gás" value={p.gas} set={v=>setP({...p,gas:v})}/></div></>}{step===3&&<><h1>Como será a execução?</h1><div className="v4-toggle-grid"><Toggle label="Empregados próprios" value={p.hasEmployees} set={v=>setP({...p,hasEmployees:v})}/><Toggle label="Diferentes empreiteiros / empresas" value={p.multipleContractors} set={v=>setP({...p,multipleContractors:v})}/><Toggle label="Trabalho em altura" value={p.workAtHeight} set={v=>setP({...p,workAtHeight:v})}/></div></>}{error&&<div className="v4-form-error">{error}</div>}<div className="v4-setup-actions"><button disabled={step===0||busy} onClick={()=>setStep(Math.max(0,step-1))}>Voltar</button>{step<3?<button className="v4-primary" onClick={()=>setStep(step+1)}>Continuar <ArrowRight size={16}/></button>:<button className="v4-primary" onClick={finish} disabled={busy}>{busy?'Montando jornada…':'Criar jornada automática'} <Sparkles size={16}/></button>}</div></section></div>
}
function Toggle({label,value,set}:{label:string;value:boolean;set:(v:boolean)=>void}){return <button type="button" className={`v4-toggle ${value?'on':''}`} onClick={()=>set(!value)}><span>{value?<Check size={16}/>:null}</span><b>{label}</b></button>}

function Router(props:any){
  const{view,setView,b,user,staff,reload,notify,selectedStage,setSelectedStage,openStage,openCopilot,copilotTab,setCopilotTab}=props
  if(view==='dashboard')return <VicoOverview b={b} staff={staff} openStage={openStage} openCopilot={openCopilot} setView={setView}/>
  if(view==='planning')return <MotorPlanning projectId={b.project.id} staff={staff} notify={notify}/>
  if(view==='field')return <FieldOperations projectId={b.project.id} notify={notify}/>
  if(view==='workforce')return <WorkforcePlanning projectId={b.project.id} notify={notify}/>
  if(view==='roadmap')return <Roadmap b={b} user={user} staff={staff} reload={reload} notify={notify} selectedStage={selectedStage} setSelectedStage={setSelectedStage}/>
  if(view==='photos')return <Photos b={b} reload={reload} notify={notify}/>
  if(view==='architecture')return <Architecture b={b} user={user} staff={staff} reload={reload} notify={notify}/>
  if(view==='engineering')return <Engineering b={b} staff={staff} reload={reload} notify={notify}/>
  if(view==='city')return <Discipline b={b} user={user} staff={staff} reload={reload} notify={notify} tag="PREFEITURA & REGULARIZAÇÃO" title="O caminho até a obra regularizada." text="A VIÇO organiza as ações municipais e federais no momento em que entram na jornada." filters={['prefeitura','federal']} icon={Landmark}/>
  if(view==='safety')return <SafetyWorkspace projectId={b.project.id} notify={notify} staff={staff}/>
  if(view==='documents')return <DocumentsWorkspace projectId={b.project.id} notify={notify} staff={staff}/>
  if(view==='finance')return <Finance b={b}/>
  if(view==='memory')return <Memory b={b} staff={staff} reload={reload}/>
  if(view==='copilot')return <Copilot b={b} tab={copilotTab} setTab={setCopilotTab}/>
  return <Settings b={b} reload={reload} notify={notify}/>
}

function Head({tag,title,text,right}:{tag:string;title:string;text:string;right?:any}){return <div className="v4-page-head"><div><span>{tag}</span><h1>{title}</h1><p>{text}</p></div>{right}</div>}
function Badge({d}:{d:string}){const m=META[d]||{label:human(d),color:'#60736A'};return <span className="v4-badge" style={{'--c':m.color} as any}>{m.label}</span>}
function progressOf(b:Bundle,filters:string[]){const list=b.tasks.filter(t=>filters.includes(t.discipline)&&t.status!=='na');return list.length?Math.round(list.filter(t=>t.status==='done').length/list.length*100):0}

function Metric({icon:I,label,value}:{icon:any;label:string;value:string}){return <article className="v4-metric"><I size={18}/><div><small>{label}</small><b>{value}</b></div></article>}
function StageTile({stage,photo,index,onClick}:{stage:Stage;photo?:Photo;index:number;onClick:()=>void}){const I=STAGE_ICONS[Math.min(index,STAGE_ICONS.length-1)]||Layers3;return <button className={`v4-stage-tile ${stage.progress===100?'complete':''}`} onClick={onClick}><div className={`v4-stage-media ${photo?'photo':''}`} style={photo?{backgroundImage:`linear-gradient(180deg,rgba(10,28,22,.05),rgba(10,28,22,.62)),url(${photo.data_url})`}:undefined}>{!photo&&<I size={28}/>}<span>{stage.num}</span><b>{stage.progress}%</b></div><div className="v4-stage-copy"><h4>{stage.title}</h4><p>{stage.done}/{stage.applicable} concluídos</p><i><em style={{width:`${stage.progress}%`}}/></i></div></button>}

function Roadmap({b,user,staff,reload,notify,selectedStage,setSelectedStage}:{b:Bundle;user:User;staff:boolean;reload:()=>void;notify:(m:string)=>void;selectedStage:string|null;setSelectedStage:(v:string|null)=>void}){
  const[addStage,setAddStage]=useState(false),[stageTab,setStageTab]=useState<'guide'|'checklist'>('checklist')
  useEffect(()=>{if(selectedStage)setStageTab('checklist')},[selectedStage])
  const stage=selectedStage?b.stages.find(s=>s.key===selectedStage):null
  if(stage){const list=b.tasks.filter(t=>t.stage_key===stage.key);const cover=b.photos.find(p=>p.stage_key===stage.key);return <div className="v4-page"><button className="v4-back" onClick={()=>setSelectedStage(null)}><ArrowLeft size={16}/> Todas as etapas</button><section className={`v4-stage-detail-hero ${cover?'has-photo':''}`} style={cover?{backgroundImage:`linear-gradient(90deg,rgba(15,39,31,.94),rgba(15,39,31,.48)),url(${cover.data_url})`}:undefined}><div><span>ETAPA {stage.num}</span><h1>{stage.title}</h1><p>{stage.summary}</p></div><div><b>{stage.progress}%</b><small>{stage.done} de {stage.applicable} concluídos</small></div></section><div className="v4-stage-tabs"><button className={stageTab==='guide'?'active':''} onClick={()=>setStageTab('guide')}><FileSearch size={15}/> Guia da etapa</button><button className={stageTab==='checklist'?'active':''} onClick={()=>setStageTab('checklist')}><ListChecks size={15}/> Checklist da obra</button></div>{stageTab==='guide'?<StageGuide stageKey={stage.key} profile={b.profile}/>:<><div className="v4-guide-checklist-note"><CheckCircle2 size={16}/><span>Nem todo item precisa existir em toda obra. Use <b>Feito</b> quando foi executado e <b>Não se aplica</b> quando o item realmente não fizer parte do escopo desta obra.</span></div><div className="v4-stage-work"><div className="v4-stage-work-head"><div><span>CHECKLIST DA ETAPA</span><h3>O que precisa acontecer aqui</h3></div>{staff&&<AddTask projectId={b.project.id} stageKey={stage.key} reload={reload}/>}</div><div className="v4-task-list">{list.map(t=><TaskRow key={t.id} task={t} staff={staff} projectId={b.project.id} reload={reload} notify={notify}/>)}</div></div></>}</div>}
  return <div className="v4-page"><Head tag="JORNADA DA OBRA" title="Um mapa, não uma planilha." text="Clique em uma etapa para ver aplicabilidade, referências técnicas, passo a passo e o checklist específico desta obra." right={staff?<button className="v4-outline" onClick={()=>setAddStage(true)}><Plus size={16}/> Nova etapa</button>:null}/>{addStage&&<AddStage projectId={b.project.id} reload={reload} close={()=>setAddStage(false)}/>}<div className="v4-stage-grid v4-stage-grid-large">{b.stages.map((s,i)=><StageTile key={s.key} stage={s} photo={b.photos.find(p=>p.stage_key===s.key)} index={i} onClick={()=>setSelectedStage(s.key)}/>)}</div></div>
}
function AddStage({projectId,reload,close}:{projectId:number;reload:()=>void;close:()=>void}){const[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError('');try{await api(`/api/os/projects/${projectId}/stages`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget).entries()))});close();await reload()}catch(e:any){setError(e.message)}finally{setBusy(false)}}return <form className="v4-inline-form" onSubmit={submit}><div><label>Nome da etapa<input name="title" required placeholder="Ex.: Automação residencial"/></label><label>Descrição<input name="summary" placeholder="O que acontece nesta etapa"/></label></div>{error&&<div className="v4-form-error">{error}</div>}<div><button type="button" onClick={close}>Cancelar</button><button className="v4-primary" disabled={busy}>{busy?'Criando…':'Criar etapa'}</button></div></form>}
