function TaskRow({task,staff,projectId,reload,notify}:{task:Task;staff:boolean;projectId:number;reload:()=>void;notify:(m:string)=>void}){const[open,setOpen]=useState(false),[busy,setBusy]=useState(false);const canEdit=staff||task.client_action;async function status(s:'done'|'na'|'pending'){if(!canEdit)return notify('Este item precisa ser validado pela equipe técnica.');setBusy(true);try{await api(`/api/os/projects/${projectId}/tasks/${task.id}`,{method:'PATCH',body:JSON.stringify({status:s})});await reload();notify(s==='done'?'Item concluído.':s==='na'?'Item marcado como Não se aplica.':'Item reaberto.')}catch(e:any){notify(e.message)}finally{setBusy(false)}}async function photo(file?:File){if(!file)return;try{notify('Processando foto…');const dataUrl=await imageToDataUrl(file);await api(`/api/os/projects/${projectId}/photos/task/${task.id}`,{method:'POST',body:JSON.stringify({dataUrl})});await reload();notify('Foto vinculada ao item.')}catch(e:any){notify(e.message)}}return <article className={`v4-task ${task.status}`}><button className="v4-task-check" disabled={busy||!canEdit} onClick={()=>status(task.status==='done'?'pending':'done')}>{task.status==='done'?<Check size={16}/>:null}</button><div className="v4-task-main" onClick={()=>setOpen(!open)}><div><Badge d={task.discipline}/>{task.required&&<span className="v4-chip">previsto no roteiro</span>}{task.client_action&&<span className="v4-chip owner">proprietário</span>}{task.status==='na'&&<span className="v4-task-status-na">não se aplica</span>}</div><h4>{task.title}</h4>{open&&<><p>{task.detail||'Sem observação adicional.'}</p><small>Responsável: {role(task.role)} · prioridade {task.priority}</small></>}</div><div className="v4-task-actions">{task.status==='done'?<button onClick={()=>status('pending')}>Reabrir</button>:task.status==='na'?<button onClick={()=>status('pending')}>Reativar</button>:<button className="done" disabled={!canEdit||busy} onClick={()=>status('done')}><CheckCircle2 size={15}/><span>Feito</span></button>}<label><Camera size={15}/><span>Foto</span><input type="file" accept="image/*" capture="environment" onChange={e=>photo(e.target.files?.[0])}/></label>{task.status==='pending'&&<button className="v4-na-action" disabled={!canEdit||busy} onClick={()=>status('na')}>Não se aplica</button>}<button onClick={()=>setOpen(!open)}><ChevronDown size={15}/></button></div></article>}

function Photos({b,reload,notify}:{b:Bundle;reload:()=>void;notify:(m:string)=>void}){const[busy,setBusy]=useState(false),[caption,setCaption]=useState(''),[analysis,setAnalysis]=useState<any>(null),[lastPhoto,setLastPhoto]=useState<Photo|null>(null),[filter,setFilter]=useState('');async function upload(file?:File){if(!file)return;setBusy(true);setAnalysis(null);try{const dataUrl=await imageToDataUrl(file),r=await api(`/api/os/projects/${b.project.id}/photos/analyze`,{method:'POST',body:JSON.stringify({dataUrl,caption})});setAnalysis(r.analysis);setLastPhoto(r.photo);await reload();notify(r.analysis?.taskId?'A IA sugeriu onde a foto se encaixa.':'Foto salva.')}catch(e:any){notify(e.message)}finally{setBusy(false)}}async function link(taskId:number,markDone=false){if(!lastPhoto)return;try{const r=await api(`/api/os/projects/${b.project.id}/photos/${lastPhoto.id}/link`,{method:'PATCH',body:JSON.stringify({taskId,markDone})});await reload();setAnalysis(null);setLastPhoto(null);notify(r.needsValidation?'Foto vinculada; a conclusão precisa de validação técnica.':markDone?'Foto vinculada e item concluído.':'Foto vinculada.')}catch(e:any){notify(e.message)}}const photos=b.photos.filter(p=>(`${p.caption||''} ${p.ai_summary||''} ${p.task_title||''} ${p.stage_key||''}`).toLowerCase().includes(filter.toLowerCase()));const suggested=b.tasks.find(t=>t.id===Number(analysis?.taskId));return <div className="v4-page"><Head tag="FOTOS & EVIDÊNCIAS" title="A obra contada por imagens." text="Fotografe o canteiro. A IA sugere etapa e checklist; a confirmação final continua humana." right={<label className="v4-upload-btn"><ImagePlus size={17}/>{busy?'Analisando…':'Nova foto'}<input type="file" accept="image/*" capture="environment" disabled={busy} onChange={e=>upload(e.target.files?.[0])}/></label>}/><section className="v4-photo-intake"><div><Camera size={28}/><h3>Registro rápido</h3><p>Legenda opcional. Útil quando a imagem mostra vários serviços.</p></div><input value={caption} onChange={e=>setCaption(e.target.value)} placeholder="Ex.: elétrica do banheiro suíte"/><label><UploadCloud size={20}/><b>{busy?'Processando…':'Tirar foto ou escolher da galeria'}</b><input type="file" accept="image/*" capture="environment" disabled={busy} onChange={e=>upload(e.target.files?.[0])}/></label></section>{analysis&&lastPhoto&&<section className="v4-photo-analysis"><img src={lastPhoto.data_url}/><div><span><Sparkles size={14}/> LEITURA DA FOTO</span><h3>{analysis.summary}</h3>{analysis.safety?.length>0&&<div className="v4-alert"><AlertTriangle size={17}/><p>{analysis.safety.join(' · ')}</p></div>}{suggested?<div className="v4-suggested"><small>SUGESTÃO · confiança {Math.round(Number(analysis.confidence||0))}%</small><b>{suggested.title}</b><span>{META[suggested.discipline]?.label||human(suggested.discipline)} · {b.stages.find(s=>s.key===suggested.stage_key)?.title}</span><div><button onClick={()=>link(suggested.id,false)}>Só vincular</button><button className="v4-primary" onClick={()=>link(suggested.id,true)}><CheckCircle2 size={15}/> Vincular e concluir</button></div></div>:<ManualLink tasks={b.tasks.filter(t=>t.status==='pending')} onLink={id=>link(id,false)}/>}</div></section>}<div className="v4-toolbar"><div><Search size={16}/><input value={filter} onChange={e=>setFilter(e.target.value)} placeholder="Buscar por etapa, tarefa ou descrição"/></div><span>{photos.length} foto(s)</span></div><div className="v4-gallery">{photos.map(p=><article key={p.id}><img src={p.data_url}/><div><span>{p.stage_key?b.stages.find(s=>s.key===p.stage_key)?.title||human(p.stage_key):'Sem etapa'}</span><h4>{p.task_title||p.ai_summary||p.caption||'Registro visual'}</h4>{Array.isArray(p.ai_tags)&&p.ai_tags.length>0&&<p>{p.ai_tags.slice(0,4).join(' · ')}</p>}<small>{date(p.created_at)} · {p.uploaded_by_name||'VIÇO'}</small></div></article>)}</div></div>}
