function Safety({b,user,staff,reload,notify}:{b:Bundle;user:User;staff:boolean;reload:()=>void;notify:(m:string)=>void}){const rows=b.tasks.filter(t=>t.discipline==='sst'),pending=rows.filter(t=>t.status==='pending'),photos=b.photos.filter(p=>Array.isArray(p.ai_safety)&&p.ai_safety.length);return <div className="v4-page"><Head tag="SEGURANÇA DO TRABALHO" title="SST dentro da etapa da obra." text="Os controles aparecem quando fazem sentido para a execução, em vez de viverem isolados em uma planilha."/><section className="v4-safety-hero"><div><HardHat size={28}/><span>ITENS ATIVOS</span><b>{pending.length}</b><p>pendências no roteiro atual</p></div><div><ShieldCheck size={28}/><span>EVIDÊNCIAS VISUAIS</span><b>{photos.length}</b><p>fotos com observações de segurança</p></div></section><div className="v4-discipline-flow">{b.stages.map(s=>{const list=rows.filter(t=>t.stage_key===s.key);if(!list.length)return null;return <section key={s.key}><header><span>{s.num}</span><div><h3>{s.title}</h3><p>Controles e verificações de SST vinculados a esta etapa.</p></div></header><div className="v4-task-list">{list.map(t=><TaskRow key={t.id} task={t} staff={staff} projectId={b.project.id} reload={reload} notify={notify}/>)}</div></section>})}</div></div>}
function Finance({b}:{b:Bundle}){const spent=Number(b.project.spent||0),budget=Number(b.project.budget||0),committed=Number(b.project.committed||0),used=budget?Math.min(100,Math.round(spent/budget*100)):0;return <div className="v4-page"><Head tag="CUSTOS" title="Custos registrados da obra." text="O objetivo é conectar orçamento, compromissos e andamento, sem transformar a rotina em lançamento contábil."/><section className="v4-finance-hero"><div><small>ORÇAMENTO</small><b>{money(budget)}</b><p>Realizado {money(spent)} · comprometido {money(committed)}</p><i><em style={{width:`${used}%`}}/></i></div><div className="v4-finance-stats"><span><CircleDollarSign size={18}/><div><small>Consumido</small><b>{used}%</b></div></span><span><ClipboardCheck size={18}/><div><small>Avanço do checklist</small><b>{b.summary.progress}%</b></div></span></div></section><section className="v4-panel"><div className="v4-section-title"><div><span>AÇÕES FINANCEIRAS</span><h3>Ligadas à jornada</h3></div></div><div className="v4-simple-list">{b.tasks.filter(t=>['financeiro','suprimentos','gestao'].includes(t.discipline)).slice(0,14).map(t=><div key={t.id} className={t.status}><CheckCircle2 size={15}/><span>{t.title}</span><small>{human(t.status)}</small></div>)}</div></section></div>}
